# R-graft-1 lab copy of the GFT kernel (generated by tools/graft_patches.py --emit-kern; alygg77, Apache-2.0)
import types
GFT_ROUTE = {}   # K2A bucket -> alygg77's row boundary for both layer boundaries (R-graft-1)
GFT_PREP_GUARD_S = 240.0
try:
    from triton.experimental import gluon as _gft_glx
    from triton.experimental.gluon import language as _gft_gl
    from triton.language.extra.cuda import gdc_wait as _gft_wait, gdc_launch_dependents as _gft_launch
    _GFT_IMPORT = None
except Exception as _gft_ex:
    _GFT_IMPORT = repr(_gft_ex)
    _gft_glx = types.SimpleNamespace(jit=lambda f: f)
    _gft_gl = types.SimpleNamespace(constexpr=None)
    _gft_wait = _gft_launch = None
@_gft_glx.jit
def _graft_row_boundary(Branch, Stream, PostW, PreW, Alpha, Beta, Out, NewStream,
                        H: _gft_gl.constexpr, F: _gft_gl.constexpr, POST: _gft_gl.constexpr, V: _gft_gl.constexpr, NW: _gft_gl.constexpr,
                        PE: _gft_gl.constexpr, QE: _gft_gl.constexpr):
    # our _boundary_kernel (r20 Gluon row boundary), router copy removed
    _gft_wait()
    _gft_launch()
    row = _gft_gl.program_id(0)
    c = _gft_gl.arange(0, H, layout=_gft_gl.BlockedLayout([V], [32], [NW], [0]))
    b = _gft_gl.load(Branch + row * F + c, c < F, 0).to(_gft_gl.float32)
    if POST:
        w = _gft_gl.load(PostW + c).to(_gft_gl.float32)
        b = (b * w).to(_gft_gl.bfloat16).to(_gft_gl.float32)
    r = _gft_gl.rsqrt(_gft_gl.sum(b * b, 0) / H + PE)
    b = (b * r).to(_gft_gl.bfloat16).to(_gft_gl.float32)
    a = _gft_gl.load(Alpha + c)
    beta = _gft_gl.load(Beta + c)
    s = _gft_gl.load(Stream + row * H + c)
    ns = a * s + beta * b
    _gft_gl.store(NewStream + row * H + c, ns)
    r = _gft_gl.rsqrt(_gft_gl.sum(ns * ns, 0) / H + QE)
    w = _gft_gl.load(PreW + c).to(_gft_gl.float32)
    h = ns * r * w
    _gft_gl.store(Out + row * H + c, h)
